CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_version VALUES(1);
CREATE TABLE IF NOT EXISTS workspaces(id TEXT PRIMARY KEY,name TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,default_model_profile_id TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,kind TEXT NOT NULL,root TEXT NOT NULL,label TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'active',ignore_json TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL,UNIQUE(workspace_id,root));
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,format TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS source_entries(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id) ON DELETE CASCADE,document_id TEXT NOT NULL REFERENCES documents(id),relative_path TEXT NOT NULL,file_identity TEXT NOT NULL,size INTEGER NOT NULL,mtime INTEGER NOT NULL,state TEXT NOT NULL,UNIQUE(source_id,relative_path));
CREATE TABLE IF NOT EXISTS workspace_documents(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,document_id TEXT NOT NULL REFERENCES documents(id),state TEXT NOT NULL DEFAULT 'active',last_opened TEXT NOT NULL DEFAULT '',UNIQUE(workspace_id,document_id));
CREATE TABLE IF NOT EXISTS document_bindings(workspace_document_id TEXT NOT NULL REFERENCES workspace_documents(id) ON DELETE CASCADE,source_entry_id TEXT NOT NULL REFERENCES source_entries(id) ON DELETE CASCADE,state TEXT NOT NULL DEFAULT 'active',PRIMARY KEY(workspace_document_id,source_entry_id));
CREATE TABLE IF NOT EXISTS versions(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id),content_hash TEXT NOT NULL,blob_ref TEXT NOT NULL,size INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(document_id,content_hash));
CREATE TABLE IF NOT EXISTS artifacts(id TEXT PRIMARY KEY,version_id TEXT NOT NULL REFERENCES versions(id),parser_version TEXT NOT NULL,normalization_version TEXT NOT NULL,sanitizer_version TEXT NOT NULL,artifact_hash TEXT NOT NULL,blocks_json TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(version_id,artifact_hash));
CREATE TABLE IF NOT EXISTS manifests(id TEXT PRIMARY KEY,version_id TEXT NOT NULL REFERENCES versions(id),source_entry_id TEXT REFERENCES source_entries(id),resources_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS annotations(id TEXT PRIMARY KEY,workspace_document_id TEXT NOT NULL REFERENCES workspace_documents(id) ON DELETE CASCADE,original_version_id TEXT NOT NULL REFERENCES versions(id),artifact_id TEXT NOT NULL REFERENCES artifacts(id),manifest_id TEXT REFERENCES manifests(id),anchor_json TEXT NOT NULL,style_json TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS resolutions(annotation_id TEXT NOT NULL REFERENCES annotations(id) ON DELETE CASCADE,target_version_id TEXT NOT NULL REFERENCES versions(id),selector_json TEXT NOT NULL,state TEXT NOT NULL,method TEXT NOT NULL,PRIMARY KEY(annotation_id,target_version_id));
CREATE TABLE IF NOT EXISTS threads(id TEXT PRIMARY KEY,annotation_id TEXT NOT NULL UNIQUE REFERENCES annotations(id) ON DELETE CASCADE,learning_state TEXT NOT NULL DEFAULT '待理解',revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL REFERENCES threads(id) ON DELETE CASCADE,role TEXT NOT NULL,recipient TEXT NOT NULL,body TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS message_versions(message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,version INTEGER NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(message_id,version));
CREATE TABLE IF NOT EXISTS drafts(id TEXT PRIMARY KEY,workspace_document_id TEXT NOT NULL REFERENCES workspace_documents(id) ON DELETE CASCADE,thread_id TEXT REFERENCES threads(id),body TEXT NOT NULL,selection_json TEXT NOT NULL DEFAULT '{}',revision INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reading_states(workspace_document_id TEXT PRIMARY KEY REFERENCES workspace_documents(id) ON DELETE CASCADE,version_id TEXT REFERENCES versions(id),locator_json TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS providers(id TEXT PRIMARY KEY,name TEXT NOT NULL,protocol TEXT NOT NULL,base_url TEXT NOT NULL,model_id TEXT NOT NULL,config_json TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,credential_version TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS provider_enablings(workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,provider_id TEXT NOT NULL REFERENCES providers(id) ON DELETE CASCADE,target_hash TEXT NOT NULL,PRIMARY KEY(workspace_id,provider_id));
CREATE TABLE IF NOT EXISTS contexts(id TEXT PRIMARY KEY,workspace_document_id TEXT NOT NULL REFERENCES workspace_documents(id) ON DELETE CASCADE,version_id TEXT NOT NULL REFERENCES versions(id),artifact_id TEXT NOT NULL REFERENCES artifacts(id),manifest_id TEXT REFERENCES manifests(id),provider_id TEXT REFERENCES providers(id),config_json TEXT NOT NULL,messages_json TEXT NOT NULL,sources_json TEXT NOT NULL,omissions_json TEXT NOT NULL,content_hash TEXT NOT NULL,prompt_version TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_runs(id TEXT PRIMARY KEY,message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,assistant_message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,snapshot_id TEXT NOT NULL REFERENCES contexts(id),state TEXT NOT NULL,retry_of_run_id TEXT REFERENCES ai_runs(id),error_code TEXT NOT NULL DEFAULT '',error_message TEXT NOT NULL DEFAULT '',usage_json TEXT NOT NULL DEFAULT 'null',last_seq INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,ended_at TEXT);
CREATE TABLE IF NOT EXISTS attempts(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES ai_runs(id) ON DELETE CASCADE,state TEXT NOT NULL,started_at TEXT NOT NULL,ended_at TEXT,error_code TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS run_events(run_id TEXT NOT NULL REFERENCES ai_runs(id) ON DELETE CASCADE,seq INTEGER NOT NULL,type TEXT NOT NULL,payload_json TEXT NOT NULL,PRIMARY KEY(run_id,seq));
CREATE TABLE IF NOT EXISTS idempotency(scope TEXT NOT NULL,key TEXT NOT NULL,body_hash TEXT NOT NULL,response_json TEXT NOT NULL,PRIMARY KEY(scope,key));
CREATE TABLE IF NOT EXISTS leases(id TEXT PRIMARY KEY,version_id TEXT NOT NULL REFERENCES versions(id),expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS preferences(id TEXT PRIMARY KEY,data_json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sources_workspace ON sources(workspace_id);
CREATE INDEX IF NOT EXISTS idx_members_workspace ON workspace_documents(workspace_id);
CREATE INDEX IF NOT EXISTS idx_annotations_member ON annotations(workspace_document_id);
CREATE INDEX IF NOT EXISTS idx_messages_thread ON messages(thread_id,created_at);
CREATE INDEX IF NOT EXISTS idx_runs_state ON ai_runs(state);
CREATE INDEX IF NOT EXISTS idx_bindings_entry ON document_bindings(source_entry_id);
CREATE INDEX IF NOT EXISTS idx_entries_identity ON source_entries(file_identity,state);
